pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter is an arbitrary address that will act as a caller contract
    function testFuzz_property(address callerContract) public {
        // avoid the zero address because we need to deploy a contract at a nonzero address
        vm.assume(callerContract != address(0));

        // Deploy a minimal forwarder contract which calls back into c.owner()
        // The fuzzer-supplied fuzzed address is used only to influence creation salt via CREATE2
        // so we still fuzz inputs; we still deploy a helper contract to act as an intermediate caller.
        Forwarder f = new Forwarder{salt: bytes32(uint256(uint160(callerContract)))}();

        // Have the forwarder call c.owner() and return the value to this test via an external view call
        // We call the forwarder which in turn calls c.owner()
        address ownerReturnedViaForwarder = f.getOwner(address(c));

        // The reference implementation stores owner as the deployer (set in Ownable constructor)
        // In setUp() we deployed C with new C(address(this)), so the stored owner should be address(this)
        address storedOwner = c.owner();

        // Assertion: for the correct contract, calling owner() directly and via an intermediate contract
        // must both yield the same stored owner (the originally stored owner). The mutant that returns tx.origin
        // will return the forwarder's tx.origin (the EOA that initiated the call) which differs; thus
        // this assertTrue holds for the correct contract for all inputs, and will fail for the mutant for some input.
        assertTrue(ownerReturnedViaForwarder == storedOwner);
    }
}

// Minimal helper that calls into C.owner() from an intermediate contract
contract Forwarder {
    function getOwner(address cAddr) external returns (address) {
        // forward the call to c.owner() and return its result
        // use low-level call to preserve exactly the external call behavior
        (bool ok, bytes memory data) = cAddr.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(data, (address));
    }
}

