contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed param: an address that will act as a contract caller (we will deploy a tiny forwarder at that address)
    function testFuzz_property(address callerSalt) public {
        // Keep the domain wide but non-zero to avoid the trivial zero-address deploy salt
        // The fuzzer provides callerSalt; we'll derive deterministic creation using CREATE2-like salt via new contract with constructor arg
        // Deploy a minimal forwarder contract that calls c.owner() from its context.
        Forwarder f = new Forwarder(address(c));

        // Call owner() directly from EOA (this test contract / deployer). This should equal the stored owner (deployer = address(this) at C construction)
        address ownerDirect = c.owner();

        // Now have the forwarder call owner() and return the value it observed
        address ownerViaContract = f.getOwner();

        // General rule: reference returns stored owner (deployer) even when called via contract; mutant would return tx.origin (the original EOA that initiated the txn), which differs when the contract is the immediate caller.
        // For our setup: c was deployed in setUp() and its owner() should be address(this) (the test contract deployed it). When we call through Forwarder, tx.origin is still the EOA running the test (the cheatvm EOA), which is address(this) in forge tests for direct calls — however the key distinction is that the reference returns stored owner (the test contract that constructed C), while the mutant returns tx.origin (the EOA that initiated the transaction). In our test environment, these are different: the constructor owner is address(this) at deployment time (the test contract), whereas tx.origin when executing the forwarder's call is the external test runner EOA (not the test contract). To ensure these are different in the fuzz environment, we check inequality possibility by asserting the reference's value equals the stored owner (observed directly) — this holds for all inputs — and the mutant will be catchable by the fuzzer when ownerViaContract != ownerDirect.

        // Single assertion: in the reference contract, both direct and via-contract calls must return the SAME stored owner (the recorded owner at construction).
        // This universal property holds for the reference but is violated by the mutant for some inputs (the fuzzer can find differences in call contexts). We assert equality observed via public interface.
        assertTrue(ownerDirect == ownerViaContract);
    }
}

// Minimal forwarder that calls owner() on the target contract from an external contract context
contract Forwarder {
    C target;
    constructor(address _target) {
        target = C(_target);
    }
    function getOwner() external view returns (address) {
        return target.owner();
    }
}

