import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzz a random caller address (will be used to deploy a Caller contract) so the fuzzer can find a case
    // where tx.origin != stored owner (deployer) — i.e. any non-deployer EOA will do; keep wide domain
    function testFuzz_property(address fuzzDeployer) public {
        // Avoid zero address which is usually not interesting
        vm.assume(fuzzDeployer != address(0));
        // Ensure fuzzDeployer is not the deployer (this test contract) so tx.origin can differ
        vm.assume(fuzzDeployer != address(this));

        // Deploy a small helper that calls c.owner() from its context.
        // We must deploy it from a fuzzed EOA to make tx.origin = fuzzDeployer and msg.sender = callerContract
        vm.prank(fuzzDeployer);
        Caller caller = new Caller();

        // Now have the caller contract call c.owner() and return what it observes.
        address observedOwner = caller.call_owner(address(c));

        // The reference implementation should return the stored owner (the deployer of C), which is address(this)
        // because we deployed c in setUp() with new C(address(this)). The single assertion checks that the
        // value observed when a CONTRACT calls owner() equals the stored owner (owner() getter), which is true
        // for the reference but can be false for the mutant that returns tx.origin.
        // Read the canonical getter directly from c to compare: this reads the contract's public owner() view.
        address storedOwner = c.owner();

        // Exactly one assertion required. For the correct contract, when a contract (Caller) calls c.owner(),
        // the returned value should equal the stored owner; the mutant that returns tx.origin will return
        // fuzzDeployer instead, making this assert fail for some fuzzDeployer values (when fuzzDeployer != storedOwner).
        assertTrue(observedOwner == storedOwner);
    }
}

// Minimal helper contract that simply calls owner() on the target and returns the value.
contract Caller {
    function call_owner(address target) external returns (address) {
        // call the owner() getter of C and return its result
        return C(payable(target)).owner();
    }
}

