import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // General rule: the on-chain stored owner equals the deployer of the contract.
    // We fuzz a candidate deployer address and simulate that address calling owner() via vm.prank.
    // The reference returns that caller (deployer) address; the mutant returns address(this) breaking the rule for some fuzzed addresses.
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Simulate the caller invoking the view owner() to observe what owner() returns to that caller.
        bool ok;
        address observed;
        vm.prank(caller);
        try c.owner() returns (address v) {
            ok = true;
            observed = v;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The reference contract's owner() should always return the stored owner (the deployer of C),
        // which equals the original deployer (the address that executed the constructor). In setUp we deployed
        // C from address(this), so the stored owner must be address(this). Thus for any caller the view returns address(this).
        // The mutant returns address(c) instead, which for some fuzzed callers differs from address(this).
        assertTrue(ok && observed == address(this));
    }
}

